package com.citacloud.springboot.contacloud.app.views;

import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.security.TenantContext;import com.citacloud.springboot.contacloud.app.services.*;import com.citacloud.springboot.contacloud.app.views.components.*;
import com.vaadin.flow.component.*;import com.vaadin.flow.component.combobox.ComboBox;import com.vaadin.flow.component.dialog.Dialog;import com.vaadin.flow.component.html.*;import com.vaadin.flow.component.notification.Notification;import com.vaadin.flow.component.orderedlayout.*;import com.vaadin.flow.component.select.Select;import com.vaadin.flow.component.textfield.TextField;import com.vaadin.flow.data.value.ValueChangeMode;import com.vaadin.flow.router.*;import com.vaadin.flow.server.*;import jakarta.annotation.security.PermitAll;
import org.slf4j.*;import java.io.ByteArrayInputStream;import java.math.BigDecimal;import java.text.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

@Route(value="inventario/existencias",layout=MainLayout.class) @PageTitle("Existencias de inventario | ContaCloud") @PermitAll
public class InventarioExistenciasView extends VerticalLayout implements BeforeEnterObserver {
 private static final Logger LOGGER=LoggerFactory.getLogger(InventarioExistenciasView.class);private static final DecimalFormat NUMBER=new DecimalFormat("#,##0.00");
 private final ExistenciaInventarioConsultaService service;private final ExistenciaInventarioReporteService reports;private final EmpresaModuloService modules;private ExistenciaInventarioCatalogosDto catalogs;
 public InventarioExistenciasView(ExistenciaInventarioConsultaService service,ExistenciaInventarioReporteService reports,EmpresaModuloService modules){this.service=service;this.reports=reports;this.modules=modules;addClassName("cc-page");setPadding(false);setSpacing(false);setWidthFull();add(new AppPageHeader("EXISTENCIAS","Consulta cuánto inventario tienes actualmente y en qué almacén se encuentra."));}
 @Override public void beforeEnter(BeforeEnterEvent event){if(!modules.habilitado("INVENTARIO")||!can("inventario_existencias.ver")){Notification.show("No tienes permiso para acceder a esta opción.");event.rerouteTo(DashboardView.class);return;}try{catalogs=service.catalogos();build();}catch(RuntimeException ex){error(ex,"No fue posible consultar las existencias. Intente nuevamente.");}}
 private void build(){
  TextField search=new TextField("Buscar");search.setPlaceholder("Buscar por producto, código...");search.setClearButtonVisible(true);search.setValueChangeMode(ValueChangeMode.LAZY);ComboBox<ExistenciaInventarioCatalogosDto.Opcion> branch=combo("Sucursal",catalogs.sucursales());ComboBox<ExistenciaInventarioCatalogosDto.AlmacenOpcion> warehouse=warehouseCombo(catalogs.almacenes());ComboBox<ExistenciaInventarioCatalogosDto.Opcion> category=combo("Categoría",catalogs.categorias());Select<String> state=new Select<>();state.setLabel("Estado");state.setItems("Activos","Inactivos","Todos");state.setValue("Activos");Select<String> stock=new Select<>();stock.setLabel("Stock");stock.setItems("Todos","Con existencia","Sin existencia","Existencia negativa");stock.setValue("Todos");AppActionButton refresh=new AppActionButton(ActionType.REFRESH,ButtonSize.MAIN,"Actualizar",null);AppActionButton pdf=new AppActionButton(ActionType.PRINT,ButtonSize.MAIN,"Generar PDF",null);pdf.setVisible(can("inventario_existencias.pdf"));HorizontalLayout filters=new HorizontalLayout(search,branch,warehouse,category,state,stock,refresh,pdf);filters.addClassName("cc-filter-bar");filters.setAlignItems(Alignment.END);filters.setWidthFull();filters.expand(search);
  AppGrid<ExistenciaInventarioDto> grid=grid();AppPagination[] pages=new AppPagination[1];String[] order={"producto"},direction={"ASC"};Span updated=new Span();updated.addClassName("cc-muted");Runnable load=()->{try{var r=pages[0].currentRequest();var result=service.buscar(search.getValue(),id(branch),idWarehouse(warehouse),id(category),stateValue(state),stockValue(stock),r.page(),r.size(),order[0],direction[0]);grid.setItems(result.pagina().getContent());pages[0].setTotal(result.pagina().getTotalElements());updated.setText("Actualizado: "+DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm").format(LocalDateTime.now()));pdf.setEnabled(result.pagina().getTotalElements()>0);}catch(RuntimeException ex){grid.setItems(List.of());pages[0].setTotal(0);pdf.setEnabled(false);error(ex,"No fue posible consultar las existencias. Intente nuevamente.");}};
  pages[0]=new AppPagination(r->load.run());grid.addSortListener(e->{if(!e.isFromClient())return;var selected=e.getSortOrder().stream().findFirst();order[0]=selected.map(x->x.getSorted().getKey()).orElse("producto");direction[0]=selected.map(x->x.getDirection().name()).orElse("ASC");pages[0].reset();load.run();});refresh.addClickListener(e->load.run());pdf.addClickListener(e->generatePdf(pdf,()->reports.generar(search.getValue(),id(branch),idWarehouse(warehouse),id(category),stateValue(state),stockValue(stock))));search.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});for(HasValue<?,?> f:List.of(category,state,stock))f.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});branch.addValueChangeListener(e->{if(e.isFromClient()){warehouse.clear();warehouse.setItems(catalogs.almacenes().stream().filter(x->e.getValue()==null||e.getValue().id().equals(x.sucursalId())).toList());pages[0].reset();load.run();}});warehouse.addValueChangeListener(e->{if(e.isFromClient()){pages[0].reset();load.run();}});HorizontalLayout status=new HorizontalLayout(updated);status.setWidthFull();status.setJustifyContentMode(JustifyContentMode.END);add(filters,grid,pages[0],status);load.run();
 }
 private AppGrid<ExistenciaInventarioDto> grid(){AppGrid<ExistenciaInventarioDto> g=new AppGrid<>(ExistenciaInventarioDto.class);g.addColumn(ExistenciaInventarioDto::producto).setHeader("Producto").setKey("producto").setSortable(true).setFlexGrow(1);g.addColumn(ExistenciaInventarioDto::codigo).setHeader("Código").setKey("codigo").setSortable(true).setAutoWidth(true);g.addColumn(ExistenciaInventarioDto::unidad).setHeader("Unidad").setAutoWidth(true);g.addColumn(x->x.almacen()+" · "+x.sucursal()).setHeader("Almacén").setKey("almacen").setSortable(true).setFlexGrow(1);g.addComponentColumn(x->{Span value=new Span(number(x.existencia()));value.addClassName(x.existencia().signum()<0?"cc-negative-value":"cc-number-cell");return value;}).setHeader("Existencia").setKey("existencia").setSortable(true).setAutoWidth(true);g.addComponentColumn(x->new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver existencia",e->detail(x.productoId()))).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);g.setEmptyStateText("No se encontraron productos que coincidan con los filtros.");return g;}
 private void detail(UUID productId){try{var x=service.detalle(productId);Dialog d=new Dialog();d.setHeaderTitle("EXISTENCIA DEL PRODUCTO");d.setWidth("min(900px, 96vw)");Div heading=new Div(new H2(x.producto()),new Span("Código: "+x.codigo()+" · Unidad base: "+x.unidad()));heading.addClassName("cc-detail-heading");Div total=new Div(new Span("EXISTENCIA TOTAL"),new H2(number(x.total())));total.addClassNames("cc-card","cc-summary-card");AppGrid<ExistenciaInventarioDetalleDto.Distribucion> distribution=new AppGrid<>(ExistenciaInventarioDetalleDto.Distribucion.class);distribution.addColumn(ExistenciaInventarioDetalleDto.Distribucion::sucursal).setHeader("Sucursal").setFlexGrow(1);distribution.addColumn(ExistenciaInventarioDetalleDto.Distribucion::almacen).setHeader("Almacén").setFlexGrow(1);distribution.addColumn(r->number(r.existencia())).setHeader("Existencia").setAutoWidth(true);distribution.setItems(x.distribucion());d.add(heading,total,new H3("DISTRIBUCIÓN POR ALMACÉN"),distribution);d.getFooter().add(new AppActionButton(ActionType.CLOSE,ButtonSize.MAIN,"Cerrar",e->d.close()));d.open();}catch(RuntimeException ex){error(ex,"No fue posible consultar la existencia del producto.");}}
 private void generatePdf(AppActionButton button,java.util.function.Supplier<ArchivoPdfDto> generator){button.setEnabled(false);try{ArchivoPdfDto file=generator.get();StreamResource resource=new StreamResource(file.nombreArchivo(),()->new ByteArrayInputStream(file.contenido()));resource.setContentType("application/pdf");resource.setCacheTime(0);var registration=VaadinSession.getCurrent().getResourceRegistry().registerResource(resource);UI.getCurrent().getPage().open(registration.getResourceUri().toString(),"_blank");}catch(RuntimeException ex){error(ex,"No fue posible generar el PDF. Intente nuevamente.");}finally{button.setEnabled(true);}}
 private static ComboBox<ExistenciaInventarioCatalogosDto.Opcion> combo(String label,List<ExistenciaInventarioCatalogosDto.Opcion> items){ComboBox<ExistenciaInventarioCatalogosDto.Opcion> c=new ComboBox<>(label);c.setItems(items);c.setItemLabelGenerator(ExistenciaInventarioCatalogosDto.Opcion::nombre);c.setClearButtonVisible(true);c.setPlaceholder("Todas");return c;}private static ComboBox<ExistenciaInventarioCatalogosDto.AlmacenOpcion> warehouseCombo(List<ExistenciaInventarioCatalogosDto.AlmacenOpcion> items){ComboBox<ExistenciaInventarioCatalogosDto.AlmacenOpcion> c=new ComboBox<>("Almacén");c.setItems(items);c.setItemLabelGenerator(ExistenciaInventarioCatalogosDto.AlmacenOpcion::nombre);c.setClearButtonVisible(true);c.setPlaceholder("Todos");return c;}private static UUID id(ComboBox<ExistenciaInventarioCatalogosDto.Opcion> c){return c.getValue()==null?null:c.getValue().id();}private static UUID idWarehouse(ComboBox<ExistenciaInventarioCatalogosDto.AlmacenOpcion> c){return c.getValue()==null?null:c.getValue().id();}private static String stateValue(Select<String> s){return switch(s.getValue()){case"Inactivos"->"INACTIVOS";case"Todos"->"TODOS";default->"ACTIVOS";};}private static String stockValue(Select<String> s){return switch(s.getValue()){case"Con existencia"->"CON_EXISTENCIA";case"Sin existencia"->"SIN_EXISTENCIA";case"Existencia negativa"->"NEGATIVA";default->"TODOS";};}private static String number(BigDecimal x){return x==null?"0.00":NUMBER.format(x);}private static boolean can(String p){return TenantContext.principalActual().permisos().contains(p);}private static void error(RuntimeException ex,String fallback){LOGGER.error(fallback,ex);String m=ex instanceof ReglaNegocioException||ex instanceof RecursoNoEncontradoException?ex.getMessage():fallback;Notification.show(m==null||m.isBlank()?fallback:m);}
}
